/** Small, deterministic Canvas effects. All coordinates use world space. */
import {weapon} from './catalog.js';
const TAU=Math.PI*2,clamp=(v,a=0,b=1)=>Math.max(a,Math.min(b,v));
const noise=n=>{const v=Math.sin(n*127.1+311.7)*43758.5453;return v-Math.floor(v);};
const ratio=o=>clamp((o.life??1)/Math.max(.001,o.maxLife??o.life??1));
const phase=(t,reduced)=>reduced?0:t;
const kind=o=>o.ritual?'ritual':o.visualKind||weapon(o.weaponId)?.kind||o.kind||(o.mine?'mine':o.meteor?'meteor':o.pulse?'pulse':'');
const id=o=>o.weaponId||'';
const arc=(c,x,y,r,a=0,b=TAU)=>{c.beginPath();c.arc(x,y,Math.max(.01,r),a,b);};
function line(c,points){c.beginPath();for(let i=0;i<points.length;i++)i?c.lineTo(...points[i]):c.moveTo(...points[i]);c.stroke();}
function poly(c,points,fill=true){c.beginPath();points.forEach((p,i)=>i?c.lineTo(...p):c.moveTo(...p));c.closePath();fill?c.fill():c.stroke();}
function leaf(c,x,y,length,width,angle,color){c.save();c.translate(x,y);c.rotate(angle);c.fillStyle=color;c.beginPath();c.moveTo(-length*.45,0);c.quadraticCurveTo(length*.1,-width,length*.6,0);c.quadraticCurveTo(length*.05,width,-length*.45,0);c.fill();c.restore();}
function palette(o){const key=id(o);if(/blood/.test(key))return ['#a94762','#ffb8bc','#f8e2cc'];if(/frozen/.test(key))return ['#97d8ef','#e8ffff','#5c9dc6'];if(/sun_|solar|dawn|oath/.test(key))return ['#e7b958','#fff2bf','#fffbe7'];if(/witchfire/.test(key))return ['#a18bf0','#e1b3ff','#fff2da'];if(/resin/.test(key))return ['#d59b42','#ffe3a0','#805b26'];return [o.color||'#b4dcce','#ecf9ed','#557c78'];}
function ticks(c,r,count,color,rotation=0){c.strokeStyle=color;c.lineWidth=1;for(let i=0;i<count;i++){const a=i*TAU/count+rotation;line(c,[[Math.cos(a)*(r-4),Math.sin(a)*(r-4)],[Math.cos(a)*r,Math.sin(a)*r]]);}}
function flame(c,x,y,h,w,t,color,core=true){c.save();c.translate(x,y);const sway=Math.sin(t)*w*.35;c.fillStyle=color;c.beginPath();c.moveTo(-w*.5,0);c.bezierCurveTo(-w*.9,-h*.3,w*.4+sway,-h*.55,sway,-h);c.bezierCurveTo(w*.5,-h*.62,w,-h*.25,w*.5,0);c.quadraticCurveTo(0,h*.15,-w*.5,0);c.fill();if(core){c.fillStyle='#ffedb1';c.beginPath();c.moveTo(-w*.15,-1);c.quadraticCurveTo(-w*.35,-h*.35,sway*.4,-h*.65);c.quadraticCurveTo(w*.3,-h*.2,w*.2,0);c.fill();}c.restore();}
function bell(c,o,t,reduced,quality){const r=o.radius||o.size||90,p=1-ratio(o),[gold,light]=palette(o);c.save();c.translate(o.x,o.y);c.globalAlpha=o.delay>0?.24:ratio(o)*.82;c.strokeStyle=gold;c.lineWidth=1.5;const rings=quality==='low'?1:3;for(let j=0;j<rings;j++){const rad=r*(.35+.65*clamp(p+j*.19));for(let side=0;side<4;side++){arc(c,0,0,rad,side*Math.PI/2+.08,side*Math.PI/2+1.42);c.stroke();}if(quality!=='low')ticks(c,rad,12,light,j*.11);}if(!o.echo){c.save();c.rotate(reduced?0:Math.sin(t*31)*.09*(1-p));c.fillStyle='#473d28';c.strokeStyle=gold;c.lineWidth=1.7;c.beginPath();c.moveTo(-12,7);c.quadraticCurveTo(-7,1,-7,-8);c.quadraticCurveTo(0,-19,7,-8);c.quadraticCurveTo(7,1,12,7);c.closePath();c.fill();c.stroke();c.fillStyle=light;arc(c,0,8,2.5);c.fill();line(c,[[-9,3],[9,3]]);c.restore();}c.restore();}
function fireField(c,o,t,reduced,quality){const r=o.radius||60,[hot]=palette(o),p=ratio(o);c.save();c.translate(o.x,o.y);c.rotate(o.angle||0);c.globalAlpha=.18*p;c.fillStyle='#35140e';c.beginPath();c.ellipse(0,0,r,r*.58,0,0,TAU);c.fill();c.globalAlpha=.66*p;const n=quality==='low'?4:8;for(let j=0;j<n;j++){const x=(j/(n-1)-.5)*r*1.65,y=Math.sin(j*2.7)*r*.3,w=8+noise(j+o.x)*10,h=18+noise(j+o.y)*22;flame(c,x,y,h,w,phase(t*9+j*2,reduced),hot,quality!=='low');if(quality==='high'){c.fillStyle='#ffcd78';const yy=y-25-(phase(t*19,reduced)+j*11)%30;c.fillRect(x+Math.sin(j+t)*5,yy,2,3);}}c.restore();}
function waterField(c,o,t,reduced,quality){const r=o.radius||80,ice=id(o)==='frozen_ford',resin=id(o)==='resin_web',[base,light]=palette(o),p=ratio(o);c.save();c.translate(o.x,o.y);c.globalAlpha=.16*p;c.fillStyle=base;c.beginPath();const segments=quality==='low'?16:28;for(let j=0;j<=segments;j++){const a=j*TAU/segments,rim=r*(.96+.035*Math.sin(j*2+phase(t*3,reduced)));j?c.lineTo(Math.cos(a)*rim,Math.sin(a)*rim):c.moveTo(Math.cos(a)*rim,Math.sin(a)*rim);}c.closePath();c.fill();c.globalAlpha=.55*p;c.lineWidth=ice?1.5:1;c.strokeStyle=base;c.stroke();if(resin){for(let j=0;j<8;j++){const a=j*TAU/8;line(c,[[0,0],[Math.cos(a)*r*.95,Math.sin(a)*r*.95]]);}for(let j=1;j<4;j++){c.beginPath();for(let k=0;k<=8;k++){const a=k*TAU/8;k?c.lineTo(Math.cos(a)*r*j/4,Math.sin(a)*r*j/4):c.moveTo(r*j/4,0);}c.stroke();}}else if(ice){const n=quality==='low'?5:9;for(let j=0;j<n;j++){const a=j*2.4,dist=r*(.2+.65*noise(j+o.y)),x=Math.cos(a)*dist,y=Math.sin(a)*dist;c.strokeStyle=light;c.lineWidth=1;c.fillStyle=base;poly(c,[[x,y-18],[x+5,y-3],[x,y+6],[x-5,y-1]]);line(c,[[x,y-17],[x,y+4]]);}}else{const n=quality==='low'?2:4;for(let j=0;j<n;j++){const move=reduced?(j+.7)/n:((t*.27+j/n)%1);c.globalAlpha=(1-move)*.55*p;c.strokeStyle=light;arc(c,0,0,8+r*move,Math.PI*.08,Math.PI*.91);c.stroke();arc(c,0,0,8+r*move,Math.PI*1.13,Math.PI*1.8);c.stroke();}if(quality!=='low'){c.globalAlpha=.66*p;for(let j=0;j<5;j++){const a=j*2.1,cycle=reduced?.45:(t*.8+j*.2)%1,dist=r*.28+cycle*r*.25,x=Math.cos(a)*dist,y=Math.sin(a)*dist-Math.sin(cycle*Math.PI)*15;leaf(c,x,y,6,2,-a,light);}}}c.restore();}
function compassWard(c,o,t,reduced,quality){const armed=(o.armed??0)<=0,r=armed?17:14,[base,light]=palette(o);c.save();c.translate(o.x,o.y);if(o.deathMark){const progress=1-Math.max(0,o.armed)/.9;c.strokeStyle=base;c.globalAlpha=.22;c.lineWidth=1.5;arc(c,0,0,o.radius);c.stroke();c.globalAlpha=.65;c.lineWidth=2;arc(c,0,0,24+progress*10,-Math.PI/2,-Math.PI/2+TAU*progress);c.stroke();for(let j=0;j<4;j++){const a=j*TAU/4+(reduced?0:t*.8);leaf(c,Math.cos(a)*42,Math.sin(a)*42,13,3,a,light);}}c.globalAlpha=Math.min(1,ratio(o)*4+.5);c.fillStyle='#0a1b20';c.strokeStyle=base;c.lineWidth=2;arc(c,0,0,r);c.fill();c.stroke();arc(c,0,0,r-4);c.lineWidth=.8;c.stroke();ticks(c,r-2,8,light);c.save();c.rotate(reduced?-.5:Math.sin(t*1.4+o.x)*.4);c.fillStyle=armed?light:'#79847d';poly(c,[[0,-12],[4,0],[0,9],[-4,0]]);c.fillStyle=base;poly(c,[[0,0],[4,0],[0,9],[-4,0]]);c.restore();if(armed){const pulse=reduced?.5:(Math.sin(t*4)+1)/2;c.globalAlpha=.18+pulse*.18;c.strokeStyle=base;c.lineWidth=1;arc(c,0,0,23+pulse*4);c.stroke();if(quality!=='low'){for(let j=0;j<4;j++){const a=j*TAU/4+.4;leaf(c,Math.cos(a)*25,Math.sin(a)*25,10,2,a,base);}}}c.restore();}
function meteorField(c,o,t,reduced,quality){const r=o.radius||o.size||75,[base,light]=palette(o),p=1-ratio(o);c.save();c.translate(o.x,o.y);if(o.delay>0){const warning=clamp(1-o.delay/Math.max(.65,o.initialDelay||1.2));c.strokeStyle=base;c.lineWidth=1.5;c.globalAlpha=.45;for(let j=0;j<4;j++){const a=j*TAU/4+.25;arc(c,0,0,r*.8,a,a+.8);c.stroke();line(c,[[Math.cos(a)*(r*.8-8),Math.sin(a)*(r*.8-8)],[Math.cos(a)*(r*.8+8),Math.sin(a)*(r*.8+8)]]);}c.globalAlpha=.8;const fall=reduced?40:100*(1-warning),x=-fall*.65,y=-fall;c.strokeStyle=base;c.lineWidth=7;line(c,[[x-35,y-65],[x,y]]);c.strokeStyle=light;c.lineWidth=2;line(c,[[x-30,y-57],[x,y]]);c.fillStyle=base;poly(c,[[x-8,y-5],[x+2,y-11],[x+10,y+2],[x+1,y+9],[x-8,y+4]]);c.fillStyle=light;poly(c,[[x-3,y-2],[x+1,y-6],[x+4,y+3],[x-2,y+5]]);}else{c.globalAlpha=.52*(1-p);c.fillStyle='#121a20';c.beginPath();c.ellipse(0,0,r*.6,r*.35,0,0,TAU);c.fill();c.strokeStyle=base;c.lineWidth=3;arc(c,0,0,r*(.3+.7*p));c.stroke();const n=quality==='low'?5:10;for(let j=0;j<n;j++){const a=j*TAU/n,d=r*(.2+.8*p);c.strokeStyle=base;c.lineWidth=1.6;line(c,[[Math.cos(a)*r*.22,Math.sin(a)*r*.22],[Math.cos(a+.09)*d*.65,Math.sin(a+.09)*d*.65],[Math.cos(a)*d,Math.sin(a)*d]]);leaf(c,Math.cos(a)*d,Math.sin(a)*d-p*8,7,3,a,light);}c.globalAlpha=.8*(1-p);c.fillStyle=light;poly(c,[[-12,-4],[-4,-11],[6,-9],[12,4],[3,11],[-7,8]]);}c.restore();}
function ritualField(c,o,t,reduced,quality){const r=o.radius||145,[base,light]=palette(o);c.save();c.translate(o.x,o.y);c.globalAlpha=Math.min(.42,ratio(o)*2);c.fillStyle=base;arc(c,0,0,r);c.globalAlpha*=.2;c.fill();c.globalAlpha=Math.min(.55,ratio(o)*2);c.strokeStyle=base;c.lineWidth=2;arc(c,0,0,r);c.stroke();arc(c,0,0,r-9);c.lineWidth=1;c.stroke();const n=quality==='low'?8:12;for(let j=0;j<n;j++){const a=j*TAU/n+phase(t*.06,reduced);c.save();c.rotate(a);c.fillStyle=base;poly(c,[[r-16,0],[r-23,-4],[r-31,0],[r-23,4]]);c.restore();}c.globalAlpha*=.65;c.strokeStyle=light;for(let j=0;j<3;j++){const a=j*TAU/3+phase(t*.13,reduced);c.beginPath();c.moveTo(Math.cos(a)*r*.67,Math.sin(a)*r*.67);c.quadraticCurveTo(0,0,Math.cos(a+2.1)*r*.67,Math.sin(a+2.1)*r*.67);c.stroke();}c.restore();}

export function drawZone(c,z,time,reducedMotion=false,quality='high'){
 const k=kind(z),t=phase(time,reducedMotion);
 if(k==='ritual'||k==='sanctuary')ritualField(c,z,t,reducedMotion,quality);
 else if(k==='pulse')bell(c,z,t,reducedMotion,quality);
 else if(k==='trail'||k==='solar')fireField(c,z,t,reducedMotion,quality);
 else if(k==='puddle')waterField(c,z,t,reducedMotion,quality);
 else if(k==='mine')compassWard(c,z,t,reducedMotion,quality);
 else if(k==='meteor')meteorField(c,z,t,reducedMotion,quality);
 else return false;
 return true;
}

function needle(c,p,t,reduced,quality){const [gold,light]=palette(p),scale=clamp((p.radius||6)/6,.65,2);c.save();c.translate(p.x,p.y);c.rotate(p.angle||0);c.scale(scale,scale);c.globalAlpha=quality==='low'?.35:.55;c.strokeStyle=gold;c.lineWidth=3;line(c,[[-7,0],[-29,0]]);c.globalAlpha=1;c.fillStyle='#624729';poly(c,[[-14,-2],[10,-2],[18,0],[10,2],[-14,2]]);c.strokeStyle=gold;c.lineWidth=1;line(c,[[-13,-1],[12,-1],[18,0],[-13,1]]);c.strokeStyle=light;line(c,[[-7,0],[14,0]]);if(quality!=='low'){c.strokeStyle=light;c.globalAlpha=.5+Math.sin(phase(t*18,reduced))*.2;line(c,[[9,-5],[9,5]]);line(c,[[6,0],[12,0]]);}c.restore();}
function raven(c,p,t,reduced,quality){const heavy=id(p)==='watch_raven',[base,light]=palette(p),size=clamp((p.radius||10)/10,.8,1.8)*(heavy?1.2:1);c.save();c.translate(p.x,p.y);c.rotate(p.angle||0);c.scale(size,size);const flap=reduced?.45:Math.sin(t*18+p.x*.006),spread=9+8*(flap*.5+.5);if(quality!=='low'){c.globalAlpha=.18;c.fillStyle=base;for(let j=0;j<3;j++){arc(c,-18-j*8,Math.sin(j+t*5)*4,5-j);c.fill();}c.globalAlpha=1;}c.fillStyle='#2b263b';poly(c,[[4,-2],[-3,-spread],[-16,-spread*.75],[-7,-3],[-17,-1],[-10,2],[-16,spread*.7],[-3,spread],[4,3]]);c.strokeStyle=base;c.lineWidth=1;line(c,[[-10,-spread*.75],[-2,-4],[6,0],[-2,4],[-10,spread*.75]]);if(quality!=='low'){for(let side of [-1,1])for(let j=0;j<3;j++){c.strokeStyle=j===0?light:base;line(c,[[-5-j*3,side*(spread*.58+j)],[0-j*2,side*3]]);}}c.fillStyle=base;c.beginPath();c.ellipse(2,0,8,3.5,0,0,TAU);c.fill();c.fillStyle='#3c2b45';arc(c,7,-.5,4.5);c.fill();c.fillStyle='#dfc59f';poly(c,[[10,-2],[16,0],[10,2]]);c.fillStyle=light;arc(c,8,-1,1.2);c.fill();c.restore();}
function sickle(c,p,t,reduced,quality){const [base,light]=palette(p),spin=reduced?(p.angle||0):t*13+(p.angle||0),s=clamp((p.radius||6)/6,.8,1.7);c.save();c.translate(p.x,p.y);c.rotate(spin);c.scale(s,s);if(quality!=='low'){c.strokeStyle=base;c.lineWidth=2;c.globalAlpha=.3;arc(c,0,0,19,-1.9,1);c.stroke();arc(c,0,0,23,-1.3,.6);c.stroke();c.globalAlpha=1;}c.strokeStyle='#513b28';c.lineWidth=4;line(c,[[-11,7],[5,-5]]);c.strokeStyle='#bfa06f';c.lineWidth=1.3;line(c,[[-11,6],[3,-6]]);c.fillStyle=base;c.beginPath();c.moveTo(3,-7);c.bezierCurveTo(20,-21,24,7,4,17);c.bezierCurveTo(14,5,13,-5,3,-7);c.fill();c.strokeStyle=light;c.lineWidth=1;c.beginPath();c.moveTo(3,-7);c.bezierCurveTo(20,-21,24,7,4,17);c.stroke();c.restore();}
export function drawProjectile(c,p,time,reducedMotion=false,quality='high'){
 const k=kind(p),t=phase(time,reducedMotion);
 if(p.web){const [base,light]=palette(p);c.save();c.translate(p.x,p.y);c.rotate(p.angle||0);c.strokeStyle=base;c.lineWidth=3;line(c,[[-32,0],[-9,0]]);c.strokeStyle=light;c.lineWidth=1.5;for(let j=0;j<6;j++){const a=j*TAU/6;line(c,[[0,0],[Math.cos(a)*14,Math.sin(a)*14]]);}for(const radius of [7,13]){c.beginPath();for(let j=0;j<=6;j++){const a=j*TAU/6;j?c.lineTo(Math.cos(a)*radius,Math.sin(a)*radius):c.moveTo(radius,0);}c.stroke();}c.fillStyle=light;arc(c,0,0,3);c.fill();c.restore();return true;}
 if(k==='bolt'||k==='solar')needle(c,p,t,reducedMotion,quality);
 else if(k==='bird')raven(c,p,t,reducedMotion,quality);
 else if(k==='boomerang')sickle(c,p,t,reducedMotion,quality);
 else return false;
 return true;
}
function threads(c,e,t,reduced,quality){const dx=e.tx-e.x,dy=e.ty-e.y,len=Math.hypot(dx,dy)||1,nx=-dy/len,ny=dx/len,[base,light]=palette(e),n=quality==='low'?2:4,p=1-ratio(e);c.save();c.globalAlpha=ratio(e)*.85;c.lineWidth=.9;for(let j=0;j<n;j++){const off=(j-(n-1)/2)*4;c.strokeStyle=j%2?light:base;c.beginPath();c.moveTo(e.x+nx*off,e.y+ny*off);const knot=Math.sin(j*Math.PI*.8+phase(t*9,reduced))*9;c.bezierCurveTo(e.x+dx*.32+nx*knot,e.y+dy*.32+ny*knot,e.x+dx*.68-nx*knot,e.y+dy*.68-ny*knot,e.tx-nx*off,e.ty-ny*off);c.stroke();}if(quality!=='low'){const along=reduced?.55:clamp(p*1.4),x=e.x+dx*along,y=e.y+dy*along;c.fillStyle=light;poly(c,[[x+nx*4,y+ny*4],[x+dx/len*7,y+dy/len*7],[x-nx*4,y-ny*4],[x-dx/len*7,y-dy/len*7]]);}c.restore();}
function lightning(c,e,t,reduced,quality){const dx=e.tx-e.x,dy=e.ty-e.y,len=Math.hypot(dx,dy)||1,nx=-dy/len,ny=dx/len,[base,light]=palette(e),n=clamp(Math.ceil(len/23),4,quality==='low'?8:14),seed=(e.seed??e.x+e.ty)*.1,points=[[e.x,e.y]];for(let j=1;j<n;j++){const off=(noise(seed+j+(reduced?0:Math.floor(t*18)))-.5)*24;points.push([e.x+dx*j/n+nx*off,e.y+dy*j/n+ny*off]);}points.push([e.tx,e.ty]);c.save();c.globalAlpha=ratio(e);c.strokeStyle=base;c.lineWidth=quality==='low'?2:4;line(c,points);c.strokeStyle=light;c.lineWidth=1;line(c,points);if(quality!=='low'){for(let j=2;j<points.length-1;j+=4){const [x,y]=points[j],side=j%3?1:-1;c.strokeStyle=base;line(c,[[x,y],[x+nx*12*side-dx/len*4,y+ny*12*side-dy/len*4],[x+nx*23*side+dx/len*4,y+ny*23*side+dy/len*4]]);}}c.fillStyle=light;arc(c,e.tx,e.ty,2.5);c.fill();c.restore();}
function thornBlade(c,e,t,reduced,quality){const [base,light]=palette(e),r=clamp(e.size||14,9,25),a=e.angle??phase(t*4+e.x*.02,reduced);c.save();c.translate(e.x,e.y);c.rotate(a);c.globalAlpha=clamp(ratio(e)*2);if(quality!=='low'){c.globalAlpha*=.3;c.strokeStyle=base;c.lineWidth=2;arc(c,0,0,r+4,.3,3.7);c.stroke();c.globalAlpha=clamp(ratio(e)*2);}c.fillStyle='#415036';poly(c,[[-r,-3],[-r*.3,-5],[0,-r],[r*.3,-4],[r,0],[r*.1,4],[-r*.3,r*.6],[-r*.3,2]]);c.fillStyle=base;poly(c,[[-r,-3],[0,-1],[0,-r],[r*.3,-4],[r,0],[0,1],[-r*.3,r*.6]]);c.strokeStyle=light;c.lineWidth=1;line(c,[[-r+2,-2],[0,0],[r-2,0]]);c.restore();}
function flameFan(c,e,t,reduced,quality){const [base,light]=palette(e),r=e.size||160,width=e.width||1.2,p=1-ratio(e),n=quality==='low'?4:7;c.save();c.translate(e.x,e.y);c.rotate(e.angle||0);c.globalAlpha=ratio(e)*.64;for(let j=0;j<n;j++){const a=-width/2+width*j/(n-1),reach=r*(.65+.35*Math.sin(j*1.7+1)**2)*(.55+.45*p);c.save();c.rotate(a);c.strokeStyle=base;c.lineWidth=5*(1-p)+1;c.beginPath();c.moveTo(9,0);c.bezierCurveTo(reach*.35,-7+Math.sin(phase(t*12+j,reduced))*6,reach*.65,8,reach,0);c.stroke();c.strokeStyle=light;c.lineWidth=1.4;c.stroke();if(quality!=='low'){for(let k=1;k<4;k++){const x=reach*k/4;c.strokeStyle=base;c.lineWidth=1.5;line(c,[[x,0],[x+9,-8*(k%2?1:-1)],[x+20,-13*(k%2?1:-1)]]);}c.fillStyle=light;leaf(c,reach,0,10,3,0,light);}c.restore();}c.restore();}
function wardBurst(c,e,t,reduced,quality){const [base,light]=palette(e),p=1-ratio(e),r=(e.size||90)*(.25+.75*p),n=quality==='low'?6:10;c.save();c.translate(e.x,e.y);c.globalAlpha=ratio(e)*.8;c.lineWidth=2;c.strokeStyle=base;for(let j=0;j<4;j++){const a=j*TAU/4;arc(c,0,0,r,a+.1,a+1.2);c.stroke();}for(let j=0;j<n;j++){const a=j*TAU/n,d=r*.9;leaf(c,Math.cos(a)*d,Math.sin(a)*d,9,3,a,base);c.strokeStyle=light;c.lineWidth=1;line(c,[[Math.cos(a)*r*.25,Math.sin(a)*r*.25],[Math.cos(a)*r*.7,Math.sin(a)*r*.7]]);}c.restore();}
function blood(c,e,reduced,quality,stain=false){const p=1-ratio(e),seed=e.seed??e.x*.11+e.y*.07,size=clamp(e.size||19,10,60),n=quality==='low'?4:Math.min(11,e.particles||8),angle=e.angle||0;c.save();c.translate(e.x,e.y);c.globalAlpha=stain?ratio(e)*.38:ratio(e)*.85;c.fillStyle=stain?'#652c40':'#a43d56';for(let j=0;j<n;j++){const a=angle+(noise(seed+j)-.5)*TAU,d=size*(.25+.75*noise(seed+j+20))*(stain?1:reduced?.55:Math.sqrt(p)),x=Math.cos(a)*d,y=Math.sin(a)*d*(stain?.58:1)+(stain?0:p*p*8),w=(stain?2.5:1.4)+noise(seed+j+40)*2;c.beginPath();c.ellipse(x,y,w*(stain?1.6:1),w*.65,a,0,TAU);c.fill();}if(!stain&&quality!=='low'){c.fillStyle='#cab5c4';c.globalAlpha=ratio(e)*.35;for(let j=0;j<3;j++){const a=j*2.1+angle,d=size*.4*p;c.beginPath();c.ellipse(Math.cos(a)*d,Math.sin(a)*d-p*13,3*(1-p)+1,6*(1-p)+1,a,0,TAU);c.fill();}}c.restore();}
export function drawCombatEffect(c,e,time,reducedMotion=false,quality='high'){
 const k=kind(e),t=phase(time,reducedMotion);
 if(e.type==='blood')blood(c,e,reducedMotion,quality);
 else if(e.type==='stain')blood(c,e,reducedMotion,quality,true);
 else if(e.type==='line'&&k==='tether')threads(c,e,t,reducedMotion,quality);
 else if(e.type==='line'&&k==='lightning')lightning(c,e,t,reducedMotion,quality);
 else if(e.type==='orb'&&k==='orbit')thornBlade(c,e,t,reducedMotion,quality);
 else if(e.type==='cone'&&k==='cone')flameFan(c,e,t,reducedMotion,quality);
 else if(e.type==='ring'&&k==='mine')wardBurst(c,e,t,reducedMotion,quality);
 else if(e.type==='ring'&&k==='meteor')meteorField(c,{...e,radius:e.size},t,reducedMotion,quality);
 else if(e.type==='ring'&&(k==='pulse'||k==='sanctuary'))bell(c,{...e,radius:e.size,echo:true},t,reducedMotion,quality);
 else return false;
 return true;
}

/** Draw after the hero in world coordinates, below the character's feet. */
export function drawRitualMeter(c,r,time,reducedMotion=false,language='en'){
 const fill=clamp(r.ritualActive?r.ritualActive.life/r.ritualActive.maxLife:(r.ritualCharge||0)/20),ready=!r.ritualActive&&fill>=1,w=43,x=r.x-w/2,y=r.y+31;
 c.save();c.fillStyle='#071315df';c.strokeStyle=ready?'#d9b574':'#617f79';c.lineWidth=1;c.fillRect(x-2,y-2,w+4,7);c.strokeRect(x-2,y-2,w+4,7);c.fillStyle=ready?'#f3d69c':'#9aafab';c.fillRect(x,y,w*fill,3);
 if(ready){c.globalAlpha=reducedMotion?.7:.6+Math.sin(time*3)*.2;c.fillStyle='#f4d89b';poly(c,[[x-8,y+1],[x-5,y-2],[x-3,y+1],[x-5,y+4]]);poly(c,[[x+w+8,y+1],[x+w+5,y-2],[x+w+3,y+1],[x+w+5,y+4]]);c.globalAlpha=1;}
 c.fillStyle=ready?'#f0d6a4':'#b7cbc4';c.font='600 9px Arial, sans-serif';c.textAlign='center';const label=language==='lt'?(ready?'RITUALAS PARUOŠTAS':'RITUALAS'):language==='ru'?(ready?'РИТУАЛ ГОТОВ':'РИТУАЛ'):(ready?'RITUAL READY':'RITUAL');c.fillText(r.ritualActive?(language==='lt'?'RITUALAS AKTYVUS':language==='ru'?'РИТУАЛ АКТИВЕН':'RITUAL ACTIVE'):ready?(language==='lt'?'UŽDARYK RATĄ':language==='ru'?'ЗАМКНИ КРУГ':'READY · CLOSE A LOOP'):label+' '+Math.floor(fill*100)+'%',r.x,y+15);c.restore();
}
